# Part B: knowledge of crimes against women and children and the laws on them, rights in the
# Constitution, and the police procedures that protect women and children. Central Acts and the
# Constitution only; state rules and schemes, which change, are left out.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 1, "POCSO Act", "Under the Protection of Children from Sexual Offences (POCSO) Act, 2012, a 'child' is a person below what age?",
      ["18 years", "16 years", "14 years", "21 years"],
      "POCSO defines a child as anyone below 18 years, boy or girl. The Act is gender-neutral."),
    S(1, 2, "Domestic violence", "Under the Protection of Women from Domestic Violence Act, 2005, which official helps an aggrieved woman make an application and get shelter or medical help?",
      ["Protection Officer", "Lokayukta", "Returning Officer", "Revenue Inspector"],
      "The Act provides for Protection Officers, who help the woman approach the Magistrate and reach shelter homes and medical facilities. The Act covers physical, sexual, verbal, emotional and economic abuse."),
    S(1, 1, "Child marriage", "Under the Prohibition of Child Marriage Act, 2006, what is the minimum age of marriage for a woman?",
      ["18 years", "14 years", "15 years", "16 years"],
      "A woman below 18 or a man below 21 is a 'child' for this Act, and a marriage involving a child can be voided at the option of that child."),
    S(1, 1, "Dowry", "Giving or taking dowry is an offence under which Act?",
      ["Dowry Prohibition Act, 1961", "Hindu Marriage Act, 1955", "Special Marriage Act, 1954", "Indian Succession Act, 1925"],
      "The Dowry Prohibition Act, 1961 makes both giving and taking dowry, and demanding it, offences."),
    S(1, 1, "Helplines", "Which is the national helpline number for children in distress (CHILDLINE)?",
      ["1098", "100", "108", "1076"],
      "1098 connects a child in need of care or protection to help, day or night. 108 is an ambulance number."),
    S(1, 2, "Workplace harassment", "Under the Sexual Harassment of Women at Workplace Act, 2013, an employer with how many or more workers must set up an Internal Committee?",
      ["10", "20", "50", "100"],
      "Every workplace with 10 or more workers must have an Internal Committee. For smaller workplaces a Local Committee is set up in each district."),
    S(1, 2, "Right to education", "Under the Right of Children to Free and Compulsory Education Act, 2009, what share of entry-class seats must private unaided schools give to children from weaker and disadvantaged groups?",
      ["25%", "10%", "15%", "33%"],
      "Section 12 of the RTE Act requires 25% of entry-level seats for such children, with the government paying their fees. The Act covers children from 6 to 14."),
    S(1, 3, "Arrest of women", "Under the criminal procedure law, a woman may be arrested after sunset and before sunrise only in exceptional cases, with the prior permission of:",
      ["A Judicial Magistrate of the First Class", "The Superintendent of Police", "The District Collector", "The Station House Officer"],
      "This safeguard, in the old CrPC and kept in the Bharatiya Nagarik Suraksha Sanhita, 2023, needs a written report to, and prior permission of, a Judicial Magistrate of the First Class."),
    S(1, 2, "FIR", "What is a 'Zero FIR'?",
      ["An FIR any police station must register, whatever the place of the crime", "An FIR closed without any investigation", "An FIR that can be filed only online", "An FIR for an offence with no fine"],
      "A police station must record information about a cognisable offence even if the crime happened elsewhere, and then transfer it to the right station. The BNSS, 2023 gives this a clear legal basis."),
    S(1, 2, "Juvenile justice", "Under the Juvenile Justice (Care and Protection of Children) Act, 2015, who first assesses whether a child of 16 to 18 accused of a heinous offence may be tried as an adult?",
      ["The Juvenile Justice Board", "The Child Welfare Committee", "The High Court", "The Lok Adalat"],
      "The Juvenile Justice Board makes a preliminary assessment of the child's mental and physical capacity before any transfer to the Children's Court. The Child Welfare Committee deals with children in need of care."),

    # ---------- Practice Test 2 ----------
    S(2, 1, "Trafficking", "Which Article of the Constitution forbids traffic in human beings and forced labour (begar)?",
      ["Article 23", "Article 24", "Article 17", "Article 39"],
      "Article 23 bans human trafficking and forced labour. Article 24 bans child labour in factories, mines and hazardous work."),
    S(2, 2, "Women's commission", "The National Commission for Women was set up under an Act passed in which year?",
      ["1990", "1986", "1995", "2001"],
      "The National Commission for Women Act was passed in 1990 and the Commission was constituted in January 1992."),
    S(2, 2, "Maternity benefit", "After the 2017 amendment to the Maternity Benefit Act, how much paid maternity leave can a woman get for each of her first two children?",
      ["26 weeks", "12 weeks", "18 weeks", "24 weeks"],
      "The Maternity Benefit (Amendment) Act, 2017 raised paid leave from 12 to 26 weeks for the first two children; it is 12 weeks from the third child."),
    S(2, 2, "Sex determination", "Which law bans the use of medical tests to find the sex of a foetus?",
      ["PCPNDT Act, 1994", "MTP Act, 1971", "Dowry Prohibition Act, 1961", "Immoral Traffic (Prevention) Act, 1956"],
      "The Pre-Conception and Pre-Natal Diagnostic Techniques (PCPNDT) Act, 1994 bans sex selection and sex determination, to stop female foeticide."),
    S(2, 2, "Child labour", "After the 2016 amendment to the child labour law, an 'adolescent' is a person of what age?",
      ["14 to 18 years", "12 to 16 years", "10 to 14 years", "16 to 21 years"],
      "The Child and Adolescent Labour (Prohibition and Regulation) Act bans all work by children below 14 (except family work after school) and hazardous work by adolescents of 14 to 18."),
    S(2, 2, "Child rights", "The National Commission for Protection of Child Rights works under an Act of which year?",
      ["2005", "2000", "2012", "1992"],
      "The Commissions for Protection of Child Rights Act, 2005 set up the NCPCR and state commissions. They also monitor the POCSO and RTE Acts."),
    S(2, 1, "POCSO Act", "Under the POCSO Act, sexual offences against children are tried by:",
      ["A Special Court", "A Lok Adalat", "A Gram Nyayalaya", "A Family Court"],
      "POCSO cases go to designated Special Courts, which should record the child's evidence quickly and in a child-friendly way, without the child facing the accused."),
    S(2, 2, "Reservation for women", "Which constitutional amendment (2023) reserves one-third of the seats in the Lok Sabha and state assemblies for women?",
      ["106th Amendment", "73rd Amendment", "74th Amendment", "101st Amendment"],
      "The Constitution (106th Amendment) Act, 2023, the Nari Shakti Vandan Adhiniyam, reserves one-third of seats for women. It applies after the next census and delimitation."),
    S(2, 2, "Reservation for women", "What share of seats in Rajasthan's panchayati raj institutions is reserved for women?",
      ["50%", "33%", "25%", "40%"],
      "The 73rd Amendment requires at least one-third, and Rajasthan raised women's reservation in panchayats to 50% in 2008."),
    S(2, 2, "Marriage law", "The Muslim Women (Protection of Rights on Marriage) Act, 2019 made which practice an offence?",
      ["Instant triple talaq", "Polygamy", "Payment of mehr", "Marriage registration"],
      "The Act makes pronouncing instant triple talaq (talaq-e-biddat) void and punishable, following the Supreme Court's 2017 ruling."),

    # ---------- Drill only ----------
    S(0, 1, "Helplines", "Which number is the national Women Helpline for women facing violence?",
      ["181", "1098", "1930", "108"],
      "181 is the Women Helpline. 1098 is for children, 1930 for cyber fraud and 108 for an ambulance."),
    S(0, 2, "Constitution", "Which clause of the Constitution lets the State make special provisions for women and children?",
      ["Article 15(3)", "Article 14", "Article 19(1)", "Article 25"],
      "Article 15 forbids discrimination on grounds such as sex, but clause (3) allows special provisions for women and children, such as reserved seats."),
    S(0, 2, "Constitution", "The fundamental duty to renounce practices derogatory to the dignity of women is in which clause?",
      ["Article 51A(e)", "Article 51A(a)", "Article 51A(h)", "Article 51A(k)"],
      "Article 51A(e) asks citizens to promote harmony and renounce practices derogatory to the dignity of women. 51A(k) is the duty of parents to educate children."),
    S(0, 2, "Trafficking", "In which year was the Immoral Traffic (Prevention) Act passed?",
      ["1956", "1961", "1971", "2000"],
      "The Act was passed in 1956 as the Suppression of Immoral Traffic in Women and Girls Act and took its present name in a 1986 amendment. It targets trafficking for commercial sexual exploitation. Article 23 of the Constitution bans human trafficking."),
]
